mapper.update:
update collections
title = #{title}, description = #{description}, cover_image = #{coverImage}, author = #{author}, category_id = #{categoryId}, view_count = #{viewCount}, video_count = #{videoCount}, sort_order = #{sortOrder}, status = #{status}, updated_at = now()
where id = #{id}

update collections 
set video_count = (
    select count(*) 
    from video_collections 
    where collection_id = #{collectionId}
),
updated_at = now()
where id = #{collectionId}
